package kr.dwas.dwas_EQ.device

enum class SocFamily(val label: String) { MEDIA_TEK("MediaTek"), QUALCOMM("Qualcomm"), UNKNOWN("Unknown") }

data class DeviceCompatibilityInfo(
    val model: String,
    val lgsiProject: String,
    val androidVersion: Int,
    val platform: String,
    val hardware: String,
    val daxGeneration: Int?,
    val tuningCaptured: Boolean,
    val spatializerEvidence: Boolean = false,
    val fullSessionStandardFx: Boolean = false,
    val noDynamicsProcessingStandardFx: Boolean = false,
    val note: String,
    val nativeFxVerified: Boolean = false,
    val speakerSafeFourFx: Boolean = false,
    val aliases: Set<String> = emptySet(),
    val dolbyGeqRuntimeInactive: Boolean = false,
    val publicBassBoostRuntimeInactive: Boolean = false,
    val publicVirtualizerRuntimeInactive: Boolean = false,
    val isolatedSessionStrengthFx: Boolean = false,
) {
    val socFamily: SocFamily get() = when {
        hardware.startsWith("mt", ignoreCase = true) -> SocFamily.MEDIA_TEK
        hardware.equals("qcom", ignoreCase = true) || platform.startsWith("sm", ignoreCase = true) -> SocFamily.QUALCOMM
        else -> SocFamily.UNKNOWN
    }
    val capabilityOnly: Boolean get() = !tuningCaptured
}

