    fun find(model: String?): DeviceCompatibilityInfo? = models.firstOrNull { info ->
        info.model.equals(model, ignoreCase = true) || info.aliases.any { it.equals(model, ignoreCase = true) }
    }

    fun findByIdentity(
        model: String?,
        device: String?,
        product: String?,
        fingerprint: String?,
    ): DeviceCompatibilityInfo? {
        val direct = listOf(model, device, product)
            .filterNotNull()
            .firstNotNullOfOrNull(::find)
        if (direct != null) return direct
        val rawFingerprint = fingerprint.orEmpty()
        return models.firstOrNull { info ->
            rawFingerprint.contains("/${info.model}/", ignoreCase = true) ||
                rawFingerprint.contains("/${info.model}:", ignoreCase = true)
        }
    }
